suis ces instructions pour le logo :                                                <!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>WinCore Logo Néon (SVG + CSS)</title>
<style>
  :root{
    --logo-size: 220px; /* change la taille globale du logo ici */
    --bg: #070709;
    --neon1: #FF2DA8; /* magenta */
    --neon2: #19E0FF; /* cyan */
    --neon3: #FF8A00; /* orange */
    --textGlow: 0 0 18px rgba(255,138,0,0.95);
  }

  body{
    margin:0;
    min-height:100vh;
    background: radial-gradient(1200px 600px at 20% 40%, rgba(0,160,255,0.06), transparent 10%),
                radial-gradient(900px 400px at 80% 60%, rgba(255,30,180,0.04), transparent 10%),
                var(--bg);
    font-family: Inter, "Segoe UI", Roboto, system-ui, -apple-system, "Helvetica Neue", Arial;
    color: #fff;
  }

  /* zone header/logo top-left */
  .site-header{
    height: var(--logo-size);
    display:flex;
    align-items:flex-start;
    padding:18px 28px;
  }

  .logo-wrap{
    width: var(--logo-size);
    height: var(--logo-size);
    display:flex;
    align-items:center;
    justify-content:center;
  }

  /* make svg responsive inside the block */
  .logo-wrap svg{
    width: 100%;
    height: auto;
    display:block;
  }

  /* small text label styling (WinCore under icon) */
  .logo-caption{
    margin-left:12px;
    display:flex;
    flex-direction:column;
    justify-content:center;
    line-height:1;
  }

  .logo-caption .brand{
    font-weight:700;
    font-size:calc(var(--logo-size) * 0.18);
    color: transparent;
    -webkit-text-stroke: 1.1px rgba(255,140,0,0.95);
    text-shadow: 0 0 6px rgba(255,140,0,0.65), 0 0 18px rgba(255,80,0,0.25);
    filter: drop-shadow(0 0 12px rgba(255,140,0,0.75));
  }
  .logo-caption .tag{
    font-size:calc(var(--logo-size) * 0.07);
    color: #00E0CC;
    opacity:0.9;
    margin-top:2px;
    text-shadow: 0 0 6px rgba(0,224,204,0.75);
  }

  /* small helper for dark header look */
  .header-right{
    margin-left:auto;
    display:flex;
    align-items:center;
    gap:12px;
    color:#cfd6dc;
    font-size:14px;
    opacity:0.95;
  }

  /* Responsive: reduce size on small screens */
  @media (max-width:680px){
    :root{ --logo-size:140px; }
    .logo-caption .brand{ font-size:calc(var(--logo-size) * 0.16); }
  }
</style>
</head>
<body>

<header class="site-header" role="banner">
  <!-- Logo block: SVG + optional caption -->
  <div class="logo-wrap" aria-hidden="true">
    <!-- SVG Neon Shield + W + circuit lines -->
    <svg viewBox="0 0 600 600" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="WinCore logo neon">
      <defs>
        <!-- neon gradients -->
        <linearGradient id="g-neon" x1="0" x2="1">
          <stop offset="0" stop-color="#FF2DA8"/>
          <stop offset="0.45" stop-color="#19E0FF"/>
          <stop offset="1" stop-color="#FF8A00"/>
        </linearGradient>

        <!-- stroke glow filter -->
        <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur stdDeviation="8" result="blur1"/>
          <feMerge>
            <feMergeNode in="blur1"/>
            <feMergeNode in="SourceGraphic"/>
          </feMerge>
        </filter>

        <!-- subtle inner glow -->
        <filter id="innerGlow" x="-30%" y="-30%" width="160%" height="160%">
          <feGaussianBlur stdDeviation="3" result="b"/>
          <feComposite in="SourceGraphic" in2="b" operator="over"/>
        </filter>

        <!-- neon stroke style -->
        <style type="text/css"><![CDATA[
          .strokeNeon { stroke: url(#g-neon); stroke-width:14; stroke-linecap:round; stroke-linejoin:round; fill:none; filter:url(#glow); }
          .w-fill { fill: url(#g-neon); stroke: #fff5; stroke-width:0.6; opacity:0.98; filter: drop-shadow(0 0 12px rgba(255,45,168,0.6)); }
          .circuit { stroke: url(#g-neon); stroke-width:12; stroke-linecap:round; filter:url(#glow); fill:none; }
          .dot { fill:#FF8A00; filter: drop-shadow(0 0 10px rgba(255,138,0,0.9)); }
        ]]></style>
      </defs>

      <!-- background subtle ring (for nicer contrast) -->
      <circle cx="170" cy="210" r="180" fill="none" stroke="#04162a" stroke-width="1" opacity="0.18" />

      <!-- Shield outline (simplified crest) -->
      <path class="strokeNeon"
            d="M170 36 L270 36 L370 110 C400 150 400 240 325 310 L170 458 L15 310 C-60 240 -60 150 -30 110 L70 36 Z"
            transform="translate(90,40) scale(0.7)" />

      <!-- Stylized W shape (center) -->
      <path class="w-fill" d="M110 220 L140 320 L170 240 L200 320 L230 220 L260 350 L230 320 L200 260 L170 320 L140 240 L110 320 Z"
            transform="translate(120,20) scale(1.05)"/>

      <!-- circuit-style lines to the right of the W -->
      <path class="circuit" d="M355 160 L420 160 L480 120" />
      <path class="circuit" d="M355 200 L430 200 L490 160" />
      <path class="circuit" d="M355 240 L440 240 L500 200" />

      <!-- circuit dots -->
      <circle class="dot" cx="480" cy="120" r="12"/>
      <circle class="dot" cx="490" cy="160" r="12"/>
      <circle class="dot" cx="500" cy="200" r="12"/>

      <!-- Overglow thin strokes to accent edges -->
      <path d="M110 220 L140 320 L170 240 L200 320 L230 220" transform="translate(120,20) scale(1.05)"
            fill="none" stroke="#ffffff30" stroke-width="1" opacity="0.9"/>

      <!-- Extra subtle front glow -->
      <g transform="translate(0,0)">
        <ellipse cx="200" cy="420" rx="240" ry="50" fill="rgba(10,10,10,0.14)"/>
      </g>
    </svg>
  </div>

  <!-- Optionnel : texte WinCore (neon stroke) -->
  <div class="logo-caption" aria-hidden="true">
    <div class="brand">WinCore</div>
    <div class="tag">Solutions informatiques</div>
  </div>

  <!-- right area for demo -->
  <div class="header-right">
    <nav aria-label="Principale">
      <span>ACCUEIL</span>
      <span style="margin:0 14px;">SERVICES</span>
      <span>CONTACT</span>
    </nav>
  </div>
</header>

<!-- Explication + conseils -->
<main style="padding:20px 40px; color:#9fb3c9;">
  <h2 style="font-weight:600;">Astuces d'intégration</h2>
  <ul>
    <li>Pour placer le logo exactement en top-left d'une navbar : mettez <code>.site-header</code> dans votre header global.</li>
    <li>Adapter la taille : modifiez <code>--logo-size</code> dans :root.</li>
    <li>Remplacer par une image : si vous avez un PNG/JPEG, mettez &lt;img src="logo.png"&gt; à la place de l'&lt;svg&gt; et conservez la CSS pour l'ombre/glow.</li>
    <li>Accessibility : ajouter <code>alt</code> ou <code>aria-label</code> sur l'élément logo si vous utilisez &lt;img&gt;.</li>
  </ul>
</main>

</body>
</html>
